/** The bedside check by two different nurses or doctors, then the start (within 30 minutes of the issue). */
export interface StartIn {
  /** The patient's wristband as scanned */
  wristband_code?: string | null;
  /** When not scanned: TwoIdentifiers, or EmergencyOverride with identity_note */
  identity_check?: "WristbandScan" | "TwoIdentifiers" | "EmergencyOverride" | null;
  identity_note?: string | null;
  checks: BedsideChecks;
  /** The second nurse or doctor checks with you and co-signs */
  second_checker_username: string;
  second_checker_password: string;
}

/** The checks two people make next to the patient (II C manual p156-157); every one must be true to start. */
export interface BedsideChecks {
  /** The same identity on the notes, the collection slip, the chart, the wristband, the compatibility form and its label */
  identity: boolean;
  /** The unit number matches the bag */
  unit_number: boolean;
  /** Not expired; the expiry matches the compatibility label */
  expiry: boolean;
  /** The product matches the compatibility form, special requirements met */
  product: boolean;
  /** The bag is intact: no haemolysis, large clots, turbidity or discoloration */
  bag: boolean;
}

export interface EndIn {
  /** Stopped needs end_note */
  outcome: "Completed" | "Stopped";
  volume_given_ml?: number | null;
  /** Required when Stopped: why */
  end_note?: string | null;
}

/** The transfusion reaction report (the II C manual's format, Table 11, p163); it also reports the incident. */
export interface ReactionIn {
  noticed_at: string;
  /** As the clinician names it */
  reaction_type: string;
  signs: string;
  action_taken: string;
  possible_reason?: string | null;
  /** The type of reaction on the report form of the II A manual (Table 11) and the 2013 manual (Table 1) */
  reaction_class: "Haemolytic" | "Anaphylactic" | "DelayedHaemolytic" | "Bacterial" | "Other";
  /** Fatal (then harm is Death); otherwise non-fatal */
  fatal?: boolean;
  /** DelayedHaemolytic: the time after the transfusion */
  delayed_after?: string | null;
  /** DelayedHaemolytic: the antibody, if applicable */
  antibody?: string | null;
  /** Bacterial: the organism */
  organism?: string | null;
  /** Blood given to the wrong patient or ABO-incompatible: reported as the sentinel event TRANSFUSION_WRONG_BLOOD */
  wrong_blood?: boolean;
  harm: "NoHarm" | "Mild" | "Moderate" | "Severe" | "Death";
}

/** The unit comes back to the bank without being transfused. */
export interface ReturnIn {
  /** True: signed back into the blood refrigerator within 30 minutes of the issue; false: not given (a discrepancy, too long out, a damaged bag) and discarded */
  fit_for_use: boolean;
  /** Required when not fit for use */
  discard_reason?: "Expired" | "BagDamaged" | "OutOfStorageTooLong" | "StorageTemperature" | "IdentityDiscrepancy" | "Other" | null;
  /** Required when not fit for use: what was found */
  note?: string | null;
}

export interface IdentityVerifyOut {
  /** The band scanned is this patient's */
  match: boolean;
  scanned_mrn: string;
  /** Whose band it is (null: no patient has this MRN) */
  scanned_patient: PatientBriefOut | null;
  expected_patient: PatientBriefOut;
}

export interface PatientBriefOut {
  patient_id: number;
  full_name: string;
  mrn: string;
  gender: string | null;
  dob: string | null;
}

/** Blood requests — GET /api/v1/blood/requests (who may call: holders of blood.view). */
export function worklistBloodRequests(query?: { status?: "Open" | "Closed" | "Cancelled" | null; patient_id?: number | null; limit?: number; before_id?: number | null }): Promise<BloodRequestOut[]> {
  return api<BloodRequestOut[]>("GET", withQuery(`/blood/requests`, query), undefined);
}

/** One blood request — GET /api/v1/blood/requests/{request_id} (who may call: holders of blood.view). */
export function getRequest(request_id: number): Promise<BloodRequestDetailOut> {
  return api<BloodRequestDetailOut>("GET", `/blood/requests/${request_id}`, undefined);
}

/** One transfusion — GET /api/v1/blood/transfusions/{transfusion_id} (who may call: holders of blood.view). */
export function getTransfusion(transfusion_id: number): Promise<BloodTransfusionDetailOut> {
  return api<BloodTransfusionDetailOut>("GET", `/blood/transfusions/${transfusion_id}`, undefined);
}

/** Record observations during a transfusion — POST /api/v1/blood/transfusions/{transfusion_id}/observations (who may call: holders of blood.transfuse). */
export function observe(transfusion_id: number, body: ObservationIn): Promise<BloodTransfusionDetailOut> {
  return api<BloodTransfusionDetailOut>("POST", `/blood/transfusions/${transfusion_id}/observations`, body, { idempotent: true });
}

/** The bedside check by two people, then the start — POST /api/v1/blood/transfusions/{transfusion_id}/start (who may call: holders of blood.transfuse). */
export function startBloodTransfusions(transfusion_id: number, body: StartIn): Promise<BloodTransfusionDetailOut> {
  return api<BloodTransfusionDetailOut>("POST", `/blood/transfusions/${transfusion_id}/start`, body);
}

/** End a transfusion — POST /api/v1/blood/transfusions/{transfusion_id}/end (who may call: holders of blood.transfuse). */
export function end(transfusion_id: number, body: EndIn): Promise<BloodTransfusionDetailOut> {
  return api<BloodTransfusionDetailOut>("POST", `/blood/transfusions/${transfusion_id}/end`, body);
}

/** Report a transfusion reaction — POST /api/v1/blood/transfusions/{transfusion_id}/reaction (who may call: holders of blood.transfuse). */
export function reaction(transfusion_id: number, body: ReactionIn): Promise<BloodTransfusionDetailOut> {
  return api<BloodTransfusionDetailOut>("POST", `/blood/transfusions/${transfusion_id}/reaction`, body, { idempotent: true });
}

/** Sign a unit back, or record it as not given — POST /api/v1/blood/transfusions/{transfusion_id}/return (who may call: holders of blood.bank.operate or blood.transfuse). */
export function returnUnit(transfusion_id: number, body: ReturnIn): Promise<BloodTransfusionDetailOut> {
  return api<BloodTransfusionDetailOut>("POST", `/blood/transfusions/${transfusion_id}/return`, body);
}

/** Scan to verify a patient's identity — GET /api/v1/wristbands/verify (who may call: holders of patient.view). */
export function verifyWristband(query: { code: string; admission_id?: number | null; er_visit_id?: number | null; patient_id?: number | null }): Promise<IdentityVerifyOut> {
  return api<IdentityVerifyOut>("GET", withQuery(`/wristbands/verify`, query), undefined);
}
